function.arguments:
{"command":"cd /testbed && python3 -c "from pathlib import Path; files=['include/drivers/clock_control.h','include/drivers/i2c.h','include/drivers/kscan.h','include/drivers/led.h','include/drivers/lora.h','include/drivers/ps2.h','include/drivers/pwm.h','include/drivers/sensor.h','include/drivers/uart.h','include/drivers/video.h'];
